        </p>

      </article>



      <article class="feature">

        <svg
          class="feature-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#222"
          stroke-width="1.8"
          aria-hidden="true"
        >
          <path d="M4 4h16v16H4z"></path>
