        </p>

      </article>


    </section>



    <!-- LEARNING -->

    <section class="learning" id="learning">

      <div class="learning-content">

        <svg
          class="learning-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#222"
          stroke-width="1.7"
          aria-hidden="true"
        >
          <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path>
          <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path>
        </svg>

        <h2>
          Everything you need to keep learning
        </h2>

        <p>
          Learnly brings your study tools together in one place.
          Create study sets, practice with quizzes, and keep track
          of the subjects you're working on.
        </p>

        <p>
          Whether you're studying for a test, learning something new,
          or reviewing material for school, Learnly gives you a
          simple way to stay organized and focused.
        </p>

      </div>

    </section>



    <!-- STATS -->

    <section class="stats">


      <div class="stat">

        <svg
          class="stat-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#222"
          stroke-width="1.8"
          aria-hidden="true"
        >
          <path d="M4 19V5l8-3 8 3v14"></path>
          <path d="M8 22v-6h8v6"></path>
          <path d="M8 8h.01"></path>
          <path d="M16 8h.01"></path>
          <path d="M8 12h.01"></path>
          <path d="M16 12h.01"></path>
        </svg>

        <h2>
          K-12
        </h2>

        <p>
          Tools for every grade and subject
        </p>

      </div>



      <div class="stat">

        <svg
          class="stat-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#222"
          stroke-width="1.8"
          aria-hidden="true"
        >
          <path d="M3 6l9-4 9 4-9 4-9-4z"></path>
          <path d="M7 9v5c0 2 2.5 4 5 4s5-2 5-4V9"></path>
          <path d="M21 6v7"></path>
        </svg>

        <h2>
          College
        </h2>

        <p>
          Study smarter for your courses
        </p>

      </div>



      <div class="stat">

        <svg
          class="stat-icon"
          viewBox="0 0 24 24"
