";
  var css=[];
  css.forEach(function(href) { var l=document.createElement('link'); l.rel='stylesheet'; l.href=href; document.head.appendChild(l); });
  var style=document.createElement('style'); style.textContent="

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: Arial, Helvetica, sans-serif;
      background: #f7f7f8;
      color: #222;
      line-height: 1.6;
    }

    /* NAVIGATION */

    nav {
      min-height: 70px;
      background: white;
      border-bottom: 1px solid #e5e5e5;

      display: flex;
      align-items: center;
      justify-content: space-between;

      padding: 0 7%;

      position: sticky;
      top: 0;
      z-index: 100;
    }

    .logo {
      font-size: 27px;
      font-weight: 750;
      color: #222;
      text-decoration: none;
      letter-spacing: -1px;

      display: flex;
      align-items: center;
      gap: 9px;
    }

    .logo-icon {
      width: 30px;
      height: 30px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 22px;
    }

    .nav-links a {
      color: #555;
      text-decoration: none;
      font-size: 15px;
      transition: 0.2s;
    }

    .nav-links a:hover {
      color: #111;
    }

    .login {
      padding: 9px 17px;
      border: 1px solid #ddd;
      border-radius: 7px;
    }

    .signup {
      padding: 10px 18px;
      background: #222;
      color: white !important;
      border-radius: 7px;
    }

    /* HERO */

    .hero {
      max-width: 1100px;
      margin: auto;
      padding: 100px 30px 70px;
      text-align: center;
    }

    .hero-icon {
      width: 68px;
      height: 68px;
      margin-bottom: 22px;
    }

    .hero h1 {
      font-size: clamp(42px, 6vw, 68px);
      letter-spacing: -3px;
      line-height: 1.05;
      max-width: 850px;
      margin: auto;
    }

    .hero p {
      max-width: 680px;
      margin: 25px auto;
      font-size: 18px;
      color: #666;
    }

    .hero-buttons {
      margin-top: 35px;

      display: flex;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .primary-button,
    .secondary-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 9px;

      padding: 14px 24px;
      border-radius: 8px;

      text-decoration: none;
      font-weight: 600;

      transition: 0.2s;
    }

    .primary-button {
      background: #222;
      color: white;
    }

    .primary-button:hover {
      background: #444;
    }

    .secondary-button {
      background: white;
      color: #333;
      border: 1px solid #ddd;
    }

    .secondary-button:hover {
      background: #f2f2f2;
    }

    .button-icon {
      width: 19px;
      height: 19px;
    }

    /* QUICK ACCESS */

    .quick-access {
      max-width: 1100px;
      margin: auto;
      padding: 10px 30px 90px;
    }

    .section-title {
      text-align: center;
      margin-bottom: 35px;
    }

    .section-title h2 {
      font-size: 30px;
      letter-spacing: -1px;
    }

    .section-title p {
      color: #777;
      margin-top: 8px;
    }

    .tools-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .tool-card {
      background: white;

      border: 1px solid #e6e6e6;
      border-radius: 12px;

      padding: 25px;

      text-decoration: none;
      color: #222;

      transition:
        transform 0.2s,
        box-shadow 0.2s,
        border-color 0.2s;
    }

    .tool-card:hover {
      transform: translateY(-4px);
      border-color: #bbb;
      box-shadow: 0 8px 25px rgba(0, 0, 0, 0.07);
    }

    .tool-icon {
      width: 38px;
      height: 38px;
      margin-bottom: 17px;
    }

    .tool-card h3 {
      font-size: 18px;
      margin-bottom: 7px;
    }

    .tool-card p {
      color: #777;
      font-size: 14px;
      line-height: 1.5;
    }

    /* FEATURES */

    .features {
      max-width: 1100px;
      margin: auto;

      padding: 30px;
      padding-bottom: 100px;

      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .feature {
      background: white;
      padding: 30px;

      border: 1px solid #e6e6e6;
      border-radius: 12px;
    }

    .feature-icon {
      width: 42px;
      height: 42px;
      margin-bottom: 16px;
    }

    .feature h2 {
      font-size: 20px;
      margin-bottom: 10px;
    }

    .feature p {
      color: #666;
      font-size: 15px;
    }

    /* LEARNING */

    .learning {
      background: white;

      border-top: 1px solid #e6e6e6;
      border-bottom: 1px solid #e6e6e6;

      padding: 90px 30px;
    }

    .learning-content {
      max-width: 850px;
      margin: auto;
      text-align: center;
    }

    .learning-icon {
      width: 52px;
      height: 52px;
      margin-bottom: 20px;
    }

    .learning h2 {
      font-size: 38px;
      letter-spacing: -1px;
      margin-bottom: 20px;
    }

    .learning p {
      color: #666;
      font-size: 17px;
      margin-bottom: 18px;
    }

    /* STATS */

    .stats {
      max-width: 1000px;
      margin: auto;

      padding: 90px 30px;

      display: grid;
      grid-template-columns: repeat(3, 1fr);

      text-align: center;
      gap: 30px;
    }

    .stat-icon {
      width: 36px;
      height: 36px;
      margin-bottom: 12px;
    }

    .stat h2 {
      font-size: 40px;
      letter-spacing: -2px;
    }

    .stat p {
      color: #777;
      margin-top: 5px;
    }

    /* FOOTER */

    footer {
      background: #222;
      color: white;
      padding: 50px 7%;
    }

    .footer-content {
      max-width: 1100px;
      margin: auto;

      display: flex;
      justify-content: space-between;

      gap: 30px;
      flex-wrap: wrap;
    }

    .footer-brand h2 {
      font-size: 25px;
      margin-bottom: 10px;
    }

    .footer-brand p {
      color: #aaa;
      max-width: 450px;
    }

    .footer-links {
      display: flex;
      gap: 30px;
      flex-wrap: wrap;
    }

    .footer-links a {
      color: #aaa;
      text-decoration: none;
    }

    .footer-links a:hover {
      color: white;
    }

    .footer-bottom {
      max-width: 1100px;
      margin: 40px auto 0;

      padding-top: 20px;
      border-top: 1px solid #444;

      color: #888;
      font-size: 14px;
    }

    /* MOBILE */

    @media (max-width: 950px) {

      .tools-grid {
        grid-template-columns: repeat(2, 1fr);
      }

    }

    @media (max-width: 750px) {

      nav {
        padding: 14px 20px;
        gap: 15px;
      }

      .nav-links {
        gap: 10px;
      }

      .nav-links a:not(.login):not(.signup) {
        display: none;
      }

      .hero {
        padding: 70px 20px;
      }

      .features {
        grid-template-columns: 1fr;
      }

      .stats {
        grid-template-columns: 1fr;
      }

      .learning {
        padding: 70px 20px;
      }

    }

    @media (max-width: 500px) {

      .tools-grid {
        grid-template-columns: 1fr;
      }

      .login {
        display: none;
      }

      .hero h1 {
        letter-spacing: -2px;
      }

    }

  "; document.head.appendChild(style);
  function runInline(code) { try { var s=document.createElement('script'); s.text=code; document.body.appendChild(s); } catch(e) { console.error(e); } }
  function loadScript(src) { var s=document.createElement('script'); s.src=src; document.body.appendChild(s); }
  runInline("
  {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "name": "Learnly",
    "description": "Create flashcards, take quizzes, track your progress with advanced analytics, and master any subject with confidence. Online learning tools for K-12, college, and lifelong learners.",
    "url": "https://YOUR-DOMAIN.com"
  }
  ");runInline("


    function openHome(event) {
      if (event) event.preventDefault();

      const existing = document.getElementById("learnly-home-overlay");
      if (existing) existing.remove();

      const frame = document.createElement("iframe");
      frame.id = "learnly-home-overlay";
      frame.src = new URL("home.html", window.parent.location.href).href;
      frame.title = "Learnly Home";
      frame.setAttribute("allowfullscreen", "");
      frame.style.cssText = [
        "position:fixed",
        "inset:0",
        "width:100vw",
        "height:100vh",
        "border:0",
        "margin:0",
        "padding:0",
        "z-index:2147483647",
        "background:#fff"
      ].join(";");

      document.body.appendChild(frame);
      return false;
    }

    console.log("Learnly loaded successfully.");

  ");
})();
